// Show the key behind the token: GET /api/v2/auth/me
// Node.js 18 or newer (global fetch, FormData, Blob), no packages. Save as sample.mjs and run: node sample.mjs
// Set HUB_API_KEY (and HUB_BASE_URL for a sandbox) or replace the placeholders below.

const BASE_URL = (process.env.HUB_BASE_URL ?? 'https://hub.hbcompliance.co.uk').replace(/\/$/, '');
const API_KEY = process.env.HUB_API_KEY ?? 'hbk_replace_with_your_api_key';

/** The standard error body: { error, message, details, request_id }. */
class HubApiError extends Error {
  constructor(status, body) {
    super(body?.message ?? `HTTP ${status}`);
    this.status = status;
    this.code = body?.error;
    this.details = body?.details;
    this.requestId = body?.request_id;
  }
}

let tokens = null;

async function postJson(path, payload) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const body = await res.json().catch(() => null);
  if (!res.ok) throw new HubApiError(res.status, body);
  return body;
}

const exchangeApiKey = async () => { tokens = await postJson('/api/v2/auth/token', { api_key: API_KEY }); };

/** Sends a call with the bearer token; renews the token once on 401 invalid_token. */
async function hubFetch(path, init = {}, canRetry = true) {
  if (!tokens) await exchangeApiKey();
  const res = await fetch(`${BASE_URL}${path}`, {
    ...init,
    headers: { Accept: 'application/json', Authorization: `Bearer ${tokens.access_token}`, ...init.headers },
  });
  if (res.status === 401 && canRetry) {
    const body = await res.clone().json().catch(() => null);
    if (body?.error === 'invalid_token') {
      try { tokens = await postJson('/api/v2/auth/refresh', { refresh_token: tokens.refresh_token }); } catch { await exchangeApiKey(); }
      return hubFetch(path, init, false);
    }
  }
  if (!res.ok) throw new HubApiError(res.status, await res.json().catch(() => null));
  return res;
}

try {
  const res = await hubFetch(`/api/v2/auth/me`, { method: 'GET' });
  console.log(await res.json());
} catch (error) {
  if (!(error instanceof HubApiError)) throw error;
  console.error(`HTTP ${error.status} ${error.code}: ${error.message} (request_id ${error.requestId})`);
  if (error.details) console.error(error.details);
  process.exitCode = 1;
}

