    """The standard error body: {error, message, details, request_id}."""

    def __init__(self, status, body):
        body = body if isinstance(body, dict) else {}
        super().__init__(body.get("message", f"HTTP {status}"))
        self.status = status
        self.code = body.get("error")
        self.details = body.get("details")
        self.request_id = body.get("request_id")


def body_of(response):
    try:
        return response.json()
    except ValueError:
        return None


class HubClient:
    """Exchanges the API key for a bearer token on first use and renews it once on 401 invalid_token."""

    def __init__(self):
        self.session = requests.Session()
        self.session.headers["Accept"] = "application/json"
        self.tokens = None

    def _post_json(self, path, payload):
        response = self.session.post(f"{BASE_URL}{path}", json=payload, timeout=30)

        if not response.ok:
            raise HubApiError(response.status_code, body_of(response))

        self.tokens = response.json()

    def exchange_api_key(self):
        self._post_json("/api/v2/auth/token", {"api_key": API_KEY})

    def refresh(self):
        try:
            self._post_json("/api/v2/auth/refresh", {"refresh_token": self.tokens["refresh_token"]})
        except HubApiError:
            self.exchange_api_key()

    def request(self, method, path, **kwargs):
        if self.tokens is None:
            self.exchange_api_key()

        extra_headers = kwargs.pop("headers", {})

